import { expect, test } from './fixtures';

/**
 * GET STARTED in two parts (the FIRST READ handoff, board 1; card c209), in a real
 * browser, on /start of the shared seeded server: the parts' heads and every
 * step's row. 05's open body isn't measured here: the seeded server has no
 * extension, so FIRST READ waits on 02.
 *
 * Generated by design-tools/gen-conformance.mjs from the design handoff, and
 * checked in deliberately. These assert the frame and the measurements — the
 * part visual review reliably misses. The numbers are hand-set in the mock and
 * do not round to a spacing ladder, so a later pass that tidies them would
 * silently redraw the screen. That is what this is here to stop; it is not
 * pedantry.
 *
 * Source: doc/design/handoff/FirstRead-List.dc.html
 * Extracted at 2026-10-31T23:33:18.283Z at 1440x2400.
 *
 * Regenerating overwrites this file. Hand edits belong in a sibling spec.
 */

const base = process.env.PLAYWRIGHT_BASE_URL ?? '';

const SEL = {
	frame: 'body',
	region2: '.part:not(.next)',
	region3: '.step[data-step="repo"] .st-text',
	region4: '.step[data-step="ext"] .st-text',
	region5: '.step[data-step="library"] .st-text',
	region6: '.step[data-step="phone"] .st-text',
	region7: '.part.next',
	region8: '.step[data-step="find"] .st-text',
	region13: '.step[data-step="add"] .st-text',
	region14: '.step[data-step="download"] .st-text'
};

test('00 — GET STARTED2 OF 7 DONE — Nothing here yet.: frame matches the handoff', async ({
	page
}) => {
	await page.goto(`${base}/start`);
	await expect(page.locator(SEL.frame)).toBeVisible();

	const frameStyle = await page.locator(SEL.frame).evaluate((node) => {
		const cs = getComputedStyle(node);
		return {
			display: cs.display
		};
	});
	expect(frameStyle.display).toBe('block');
});

test('00 — GET STARTED2 OF 7 DONE — Nothing here yet.: region2 matches the handoff', async ({
	page
}) => {
	await page.goto(`${base}/start`);
	await expect(page.locator(SEL.region2)).toBeVisible();

	const region2Style = await page.locator(SEL.region2).evaluate((node) => {
		const cs = getComputedStyle(node);
		return {
			display: cs.display,
			alignItems: cs.alignItems,
			justifyContent: cs.justifyContent,
			rowGap: cs.rowGap,
			columnGap: cs.columnGap,
			paddingBottom: cs.paddingBottom,
			borderBottomWidth: cs.borderBottomWidth,
			fontSize: cs.fontSize,
			fontWeight: cs.fontWeight,
			letterSpacing: cs.letterSpacing,
			lineHeight: cs.lineHeight
		};
	});
	expect(region2Style.display).toBe('flex');
	expect(region2Style.alignItems).toBe('baseline');
	expect(region2Style.justifyContent).toBe('space-between');
	expect(region2Style.rowGap).toBe('16px');
	expect(region2Style.columnGap).toBe('16px');
	expect(region2Style.paddingBottom).toBe('12px');
	expect(region2Style.borderBottomWidth).toBe('1px');
	expect(region2Style.fontSize).toBe('13px');
	expect(region2Style.fontWeight).toBe('500');
	expect(region2Style.letterSpacing).toBe('0.78px');
	expect(region2Style.lineHeight).toBe('15.6px');
});

